ClearAll[gen, u, d, f, ia, ib, nb, s, p];
gen[n_] := Sum[u[q] Outer[Times, UnitVector[n,q+1]-UnitVector[n,q], UnitVector[n,q]], {q,1,n-1}] + Sum[d[q] Outer[Times, UnitVector[n,q]-UnitVector[n,q+1], UnitVector[n,q+1]], {q,1,n-1}];
generatorColumnSums = Simplify[Total[gen[#]] & /@ {2,3,4}];
fractions = Array[f,4]; charge = Range[0,3];
yA = ia fractions; yB = ib fractions;
neOwner = nb charge.(yA+yB);
neCompact = nb (ia+ib) charge.fractions;
electronResidual = Simplify[neOwner-neCompact];
(* Both isotope generators use this same ne, T and UV. *)
commonFractions = Simplify[(yA+yB)/(ia+ib)];
flowA = gen[4].yA; flowB = gen[4].yB;
isotopeInvariantResidual = Simplify[{Total[(flowA-ia gen[4].commonFractions)^2], Total[(flowB-ib gen[4].commonFractions)^2]}];
sigma = DiagonalMatrix[{-s,-s,2s}]; pi = DiagonalMatrix[{-p,-p,2p}];
sigmaNormSquared = Tr[Transpose[sigma].sigma];
piNormSquared = Tr[Transpose[pi].pi]; work = Tr[Transpose[pi].sigma];
stateDimensions = {40+21+1,23+9+1}; coordinateReduction = (62-33)/62;
{generatorColumnSums,electronResidual,isotopeInvariantResidual,sigmaNormSquared,piNormSquared,work,stateDimensions,coordinateReduction}
